entries[127794] = { ["name"] = "Kinder des Grabes", ["text"] = "Sofort\nKlaxxiverstärkung\nVerliehen von Rik'kal dem Sezierer.\n\nGewährt eine Chance von 50%, alle frisch getöteten Kadaver mit einem mutagenen Eiersack zu injizieren, der nach 8 Sek. explodiert und allen Nicht-Spieler-Gegnern in der Nähe Schaden zufügt und helfende Parasiten beschwört.\n\nEs kann jeweils nur eine Klaxxiverstärkung aktiv sein. Wirkt nur in der Schreckensöde.\n(Procchance: 50%, 3s Abklingzeit)" }
entries[127795] = { ["name"] = "Kinder des Grabes", ["text"] = "100 Meter Reichweite\nSofort\nInfiziert mit mutagenen Eiersäcken, die explodieren und allen in der Nähe befindlichen Nicht-Spieler-Charakteren nach 8 Sek. Schaden zufügen." }
entries[127796] = { ["name"] = "Fasshieb", ["text"] = "Sofort\nBenötigt Ochsenstil\nIhr holt mit einem Gebräufass aus und fügt allen Gegnern innerhalb von 8 Metern [10.00 * ( 1 * 1 * ( 0.898882 * (Haupthand-Min-DPS * 1 + 1 * (Haupthand-Min-DPS / 2) ) + (Angriffskraft / 14) - 1))] bis [10.00 * ( 1 * 1 * ( 0.898882 * (Haupthand-Max-DPS * 1 + 1 * (Haupthand-Max-DPS / 2) ) + (Angriffskraft / 14) + 1))] Schaden zu. Tränkt Ziele in 'Benebelnde Dämpfe' und verursacht den Effekt 'Kampfesmüdigkeit'. Erzeugt 2 Chi.\n\nBenebelnde Dämpfe\nSchleudert ein Fass Eures besten Gebräus, das das Bewegungstempo aller Gegner innerhalb von 8 Metern 15 Sek. lang um 50% verringert. Verursacht ein hohes Maß an Bedrohung.\n\nBetroffene Ziele haben eine Chance von 3%, mit ihren Nahkampfangriffen zu verfehlen und sich stattdessen selbst 1095 Schaden zuzufügen.\n\nKampfesmüdigkeit\nDemoralisiert das Ziel und verringert den von ihm verursachten körperlichen Schaden 30 Sek. lang um 10%." }
entries[127797] = { ["name"] = "Ursols Vortex", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört einen Windwirbel am Zielort, der das Bewegungstempo aller Gegner innerhalb von 8 Metern um 50% verringert.\n\nBeim ersten Versuch eines Gegners, den Wirbel zu verlassen, wird er wieder in den Mittelpunkt des Wirbels zurückgezogen.\n\nHält 10 Sek. lang an. In allen Gestalten einsetzbar." }
